#!/usr/bin/env node
// orOS — .github/scripts/emoji-data.js
// Writes emoji/data.js (the emoji picker's list, CLIP-1 W3) from two
// npm packages, fetched once into a scratch folder (never committed):
//   npm pack unicode-emoji-json@0.9.0 cldr-annotations-full@49.0.0
//   tar xzf … -C <dir>/u  and  -C <dir>/c
//   node .github/scripts/emoji-data.js <dir>/u/package <dir>/c/package
// unicode-emoji-json (MIT): the emoji, their order, group and version.
// cldr-annotations-full (Unicode-3.0): names and keywords in English,
// Greek and German. Never edit emoji/data.js by hand; run this again.
"use strict";
const fs = require("fs");
const path = require("path");

const [uDir, cDir] = process.argv.slice(2);
if (!uDir || !cDir) { console.error("usage: emoji-data.js <unicode-emoji-json dir> <cldr-annotations-full dir>"); process.exit(2); }
const MAX_VERSION = 15.0;     // newer emoji are missing on many phones and on Windows 10
const LANGS = ["en", "el", "de"];
const GROUPS = { "Smileys & Emotion": "smileys", "People & Body": "people", "Animals & Nature": "nature",
  "Food & Drink": "food", "Travel & Places": "travel", "Activities": "activities", "Objects": "objects",
  "Symbols": "symbols", "Flags": "flags" };

const groups = JSON.parse(fs.readFileSync(path.join(uDir, "data-by-group.json"), "utf8"));
const ann = {};
for (const l of LANGS) {
  ann[l] = {};
  for (const kind of ["annotations", "annotationsDerived"]) {
    const f = path.join(cDir, kind, l, "annotations.json");
    if (!fs.existsSync(f)) continue;
    const j = JSON.parse(fs.readFileSync(f, "utf8"));
    const a = (j.annotations && j.annotations.annotations) || (j.annotationsDerived && j.annotationsDerived.annotations) || {};
    for (const k of Object.keys(a)) if (!ann[l][k]) ann[l][k] = a[k];
  }
}
const noVs = (e) => e.replace(/\uFE0F/g, "");
const look = (l, e) => ann[l][e] || ann[l][noVs(e)] || null;
const fold = (x) => String(x || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/ς/g, "σ").replace(/ß/g, "ss");
const clean = (x) => String(x).replace(/[\t\n|]/g, " ").trim();

const out = [];
let n = 0;
for (const g of groups) {
  const id = GROUPS[g.name];
  if (!id) continue;
  const rows = [];
  for (const e of g.emojis) {
    if (parseFloat(e.emoji_version) > MAX_VERSION) continue;
    const names = LANGS.map((l) => { const a = look(l, e.emoji); return clean(a && a.tts ? a.tts[0] : l === "en" ? e.name : ""); });
    if (!names[0]) names[0] = clean(e.name);
    const words = new Set();
    for (const l of LANGS) {
      const a = look(l, e.emoji);
      for (const w of (a && a.default) || []) fold(w).split(/[\s:,]+/).forEach((x) => { if (x.length > 1) words.add(x); });
    }
    for (const nm of names) fold(nm).split(/[\s:,]+/).forEach((x) => words.delete(x));
    rows.push([e.emoji, names[0], names[1], names[2], [...words].join(" ")].join("\t"));
    n++;
  }
  out.push([id, rows]);
}

const header = "// orOS — emoji/data.js: GENERATED by .github/scripts/emoji-data.js, do not edit.\n" +
  "// Emoji list for the emoji picker (CLIP-1 W3): unicode-emoji-json 0.9.0 (MIT) for the emoji,\n" +
  "// order and groups (emoji " + MAX_VERSION.toFixed(1) + " and older); names and keywords from the Unicode\n" +
  "// CLDR annotations 49.0.0 (Unicode License V3). Row = emoji \\t English \\t Greek \\t German \\t\n" +
  "// other words (folded: lower case, no accents, ς→σ, ß→ss).\n" +
  "// i18n-inline-ok: emoji names in English, Greek and German are data for the search.\n";
const body = "(function (root) {\n  \"use strict\";\n  root.OROS_EMOJI = " + JSON.stringify({ v: 1, groups: out.map(([id, rows]) => ({ id: id, rows: rows.join("\n") })) }) +
  ";\n})(typeof window !== \"undefined\" ? window : globalThis);\n";
const dest = path.join(__dirname, "..", "..", "emoji", "data.js");
fs.mkdirSync(path.dirname(dest), { recursive: true });
fs.writeFileSync(dest, header + body);
console.log("emoji/data.js:", n, "emoji,", (header.length + body.length) + " bytes");
